/**
 * The antique look's three cuts of type, largest to smallest (`ANTIQUE_LABEL_STYLE`
 * sizes each): letter-spaced roman `capitals` for the titles (planets, regions),
 * `roman` upper and lower case for the middle tier (moons, clusters, nebulae),
 * `italic` as named for the stars and Cassini's numbered moons.
 */

export type AntiqueLettering = 'capitals' | 'roman' | 'italic';
